CREATE OR REPLACE VIEW public.v_servicing_stage_cards AS SELECT NULL::text AS card_id, NULL::text AS hotel_id, NULL::text AS hotel_name, NULL::text AS service_line, NULL::text AS service_variant, NULL::boolean AS orm_lite, NULL::text AS current_stage, NULL::timestamptz AS stage_entered_at, NULL::timestamptz AS created_at, NULL::timestamptz AS go_live_at, NULL::integer AS progress_done, NULL::integer AS progress_total, NULL::timestamptz AS last_updated, NULL::text AS ae_owner_id, NULL::text AS specialist_id, NULL::text AS orm_team, NULL::text AS marcom_owner_id, NULL::text AS hotel_status, NULL::boolean AS assignment_complete, true AS pending_sync, NULL::timestamptz AS meeting_created_at, NULL::date AS meeting_date, NULL::timestamptz AS specialist_handover_done_at, NULL::jsonb AS stage_events, NULL::jsonb AS lanes, NULL::text AS card_tone, NULL::jsonb AS cause_lane, NULL::integer AS form_required_filled, NULL::integer AS form_required_total, NULL::integer AS form_all_pct, NULL::text AS form_status, NULL::text AS open_ticket_id, NULL::text AS open_ticket_status, NULL::text AS open_ticket_target, NULL::text AS open_ticket_source, NULL::boolean AS row2_complete FROM public.crm_documents WHERE false;
CREATE OR REPLACE VIEW public.v_servicing_stat AS SELECT NULL::integer AS cards_total, NULL::integer AS hotels, NULL::integer AS go_live, NULL::integer AS in_progress, NULL::integer AS awaiting_caretaker, true AS pending_sync, NULL::integer AS n_red, NULL::integer AS n_amber WHERE false;
CREATE OR REPLACE VIEW public.v_servicing_pipeline AS SELECT current_stage AS stage, service_line, NULL::integer AS card_count, pending_sync, NULL::integer AS n_ok, NULL::integer AS n_amber, NULL::integer AS n_red, NULL::integer AS n_wait, NULL::integer AS max_days_in_stage, NULL::text AS max_days_hotel, NULL::integer AS n_gap FROM public.v_servicing_stage_cards WHERE false;
CREATE OR REPLACE VIEW public.v_servicing_golive_days AS SELECT card_id, hotel_id, hotel_name, service_line, created_at, go_live_at, NULL::integer AS overall_days, NULL::text AS cohort_month, pending_sync, NULL::text AS owner_label FROM public.v_servicing_stage_cards WHERE false;
CREATE VIEW public.v_servicing_phase_time AS SELECT NULL::text AS card_id, NULL::text AS hotel_id, NULL::text AS hotel_name, NULL::text AS service_variant, NULL::text AS phase, NULL::text AS lane, NULL::integer AS days, NULL::text AS zone, NULL::text AS owner_id_at_end, NULL::text AS owner_label, NULL::timestamptz AS go_live_at, NULL::boolean AS owner_fallback WHERE false;
CREATE VIEW public.v_servicing_stall_candidates AS SELECT NULL::text AS card_id, NULL::text AS hotel_id, NULL::text AS hotel_name, NULL::text AS service_line, NULL::text AS service_variant, NULL::text AS phase, NULL::text AS lane, NULL::integer AS d, NULL::text AS event_key, NULL::text AS target_role, NULL::text AS current_stage, NULL::text AS owner_id WHERE false;
GRANT SELECT ON public.v_servicing_stage_cards, public.v_servicing_stat, public.v_servicing_pipeline, public.v_servicing_golive_days, public.v_servicing_phase_time, public.v_servicing_stall_candidates TO anon, authenticated, service_role;
COMMENT ON VIEW public.v_servicing_phase_time IS 'Pending Cloud Servicing mirror. Empty until explicit seed+C5. Owner-at-end must come from assignment transition log; no inferred browser reads.';
COMMENT ON VIEW public.v_servicing_stall_candidates IS 'Pending Cloud Servicing mirror. Only running red lanes from shared servicing SLA model; never infer from empty source.';
COMMENT ON VIEW public.v_servicing_stage_cards IS 'Pending Cloud mirror; operational onboarding_card remains browser-local with nullable meeting_created_at. No new operational table or backfill.';